 function userForm(id,pending){const u=pending||S.data.users.find(u=>u.user_id===id);modal(`<h2>${u?'Edit':'Daftarkan'} User</h2><form onsubmit="event.preventDefault();PO.saveUser(this)"><div class="form-group"><label>Email akun terdaftar</label><input name="email" type="email" value="${esc(u?.email||'')}" ${u?'readonly':''} required></div><div class="form-group"><label>Nama</label><input name="name" maxlength="120" value="${esc(u?.name||'')}" required></div><div class="form-group"><label>Peran</label><select name="role">${Object.entries(roles).map(([k,n])=>`<option value="${k}" ${k===(u?.role||'sales')?'selected':''}>${n}</option>`).join('')}</select></div><div class="form-group"><label>Status</label><select name="active"><option value="true">Aktif</option><option value="false" ${u?.active===false?'selected':''}>Nonaktif</option></select></div><p class="sub">Akun baru dapat dibuat melalui tombol Buat Akun Baru atau halaman Daftar. User Sales tetap perlu dipetakan ke supplier.</p><div class="modal-actions"><button type="button" class="btn" onclick="PO.close()">Batal</button><button class="btn primary">Simpan</button></div></form>`)}
 async function saveUser(form){await command('user',{email:form.elements.email.value,name:form.elements.name.value.trim(),role:form.elements.role.value,active:form.elements.active.value==='true'},'Hak akses user disimpan.')}
 function suppliersPage(){if(S.data.me.role!=='admin')return go('dashboard');$('#main').innerHTML=heading('Supplier → Sales','Mapping menentukan akun Sales yang menerima dan melihat PO supplier.',button('Import Excel',"PO.go('import-suppliers')")+button('＋ Tambah Supplier','PO.supplierForm()',true))+`<section class="panel"><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Sales</th><th>Status</th><th></th></tr></thead><tbody>${S.data.suppliers.map(s=>`<tr><td><strong>${esc(s.name)}</strong><small>${esc(s.id)}</small></td><td>${esc(S.data.users.find(u=>u.user_id===s.sales_id)?.name||'Belum dipetakan')}</td><td>${s.active?'Aktif':'Nonaktif'}</td><td>${button('Edit Mapping',`PO.supplierForm('${s.id}')`)}</td></tr>`).join('')}</tbody></table></div></section>`}
 function supplierForm(id){const s=supplier(id);modal(`<h2>${s?'Edit':'Tambah'} Supplier</h2><form onsubmit="event.preventDefault();PO.saveSupplier(this)"><div class="form-group"><label>Kode</label><input name="id" pattern="[A-Za-z0-9_-]+" maxlength="120" value="${esc(s?.id||'')}" ${s?'readonly':''} required></div><div class="form-group"><label>Nama supplier</label><input name="name" value="${esc(s?.name||'')}" maxlength="120" required></div><div class="form-group"><label>Sales penanggung jawab</label><select name="sales_id"><option value="">Belum dipetakan</option>${S.data.users.filter(u=>u.role==='sales'&&u.active).map(u=>`<option value="${u.user_id}" ${s?.sales_id===u.user_id?'selected':''}>${esc(u.name)} · ${esc(u.email)}</option>`).join('')}</select></div><div class="form-group"><label>Status</label><select name="active"><option value="true">Aktif</option><option value="false" ${s?.active===false?'selected':''}>Nonaktif</option></select></div><p class="sub">Jika Sales diganti, akses PO supplier beralih ke Sales baru. Perubahan penugasan PO aktif tercatat di timeline.</p><div class="modal-actions"><button type="button" class="btn" onclick="PO.close()">Batal</button><button class="btn primary">Simpan</button></div></form>`)}
