 function supplierImportPage(){if(S.data.me.role!=='admin')return go('dashboard');$('#main').innerHTML=heading('Import Supplier','Tambah supplier atau perbarui nama berdasarkan kode. Mapping Sales dan status yang sudah ada tetap dipertahankan.')+`<section class="panel import-box"><h2>Unggah Excel / CSV Supplier</h2><p class="sub">Kolom: <b>kode,nama suplier</b><br>Format kode sebagai Teks di Excel agar nol awal tetap utuh. Maksimal 5 MB / 10.000 baris.<br>Supplier baru aktif dan belum dipetakan ke Sales. Setelah impor, pilih Edit Mapping sebelum menerbitkan PO.</p><div class="buttons">${button('Unduh Template CSV','PO.supplierTemplate()')}</div><input aria-label="File supplier" type="file" accept=".csv,.xlsx,.xls" onchange="PO.readSupplierImport(this.files[0])"><div id="supplier-import-review"></div></section>`}
